import { base64ToBytes } from '../../src/domain/base64';

/** A valid baseline JPEG, 32 by 18 pixels (made with macOS sips from a generated gradient PNG), for the PDF tests. */
export const JPEG_WIDTH = 32;
export const JPEG_HEIGHT = 18;

const BASE64 =
  '';

export function jpegBytes(): Uint8Array {
  const bytes = base64ToBytes(BASE64);
  if (!bytes) throw new Error('fixture is not base64');
  return bytes;
}
